package com.tekwatt.audit.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="audit_events")public class AuditEvent{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(length=30)private String actorType;@Column(length=100)private String actorId;@Column(nullable=false,length=100)private String action;@Column(nullable=false,length=100)private String resourceType;@Column(length=100)private String resourceId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AuditOutcome outcome;@Column(length=64)private String ipAddress;@Column(length=500)private String userAgent;@Column(length=100)private String correlationId;@Column(length=100)private String sourceService;@Column(columnDefinition="TEXT")private String details;@Column(nullable=false)private Instant occurredAt;@Column(nullable=false,updatable=false)private Instant recordedAt;protected AuditEvent(){}public AuditEvent(UUID t,String actorType,String actorId,String action,String resourceType,String resourceId,AuditOutcome outcome,String ip,String agent,String correlation,String source,String details,Instant occurred){id=UUID.randomUUID();tenantId=t;this.actorType=actorType;this.actorId=actorId;this.action=action;this.resourceType=resourceType;this.resourceId=resourceId;this.outcome=outcome;ipAddress=ip;userAgent=agent;correlationId=correlation;sourceService=source;this.details=details;occurredAt=occurred==null?Instant.now():occurred;recordedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getActorType(){return actorType;}public String getActorId(){return actorId;}public String getAction(){return action;}public String getResourceType(){return resourceType;}public String getResourceId(){return resourceId;}public AuditOutcome getOutcome(){return outcome;}public String getIpAddress(){return ipAddress;}public String getUserAgent(){return userAgent;}public String getCorrelationId(){return correlationId;}public String getSourceService(){return sourceService;}public String getDetails(){return details;}public Instant getOccurredAt(){return occurredAt;}public Instant getRecordedAt(){return recordedAt;}}
